    # Full uniform rows/columns form the grid separators.
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w)
                if len({grid[r][c] for r in range(h)}) == 1]
    separator_colors = {grid[r][0] for r in sep_rows}
    separator_colors.update(grid[0][c] for c in sep_cols)

    def spans(length, cuts):
        result, start = [], 0
        for cut in cuts:
            if start < cut:
                result.append((start, cut))
            start = cut + 1
        if start < length:
            result.append((start, length))
        return result

    row_spans = spans(h, sep_rows)
    col_spans = spans(w, sep_cols)

    frequencies = {}
    for row in grid:
        for value in row:
            if value not in separator_colors:
                frequencies[value] = frequencies.get(value, 0) + 1

    background = max(frequencies, key=frequencies.get)
    marker = min(frequencies, key=frequencies.get)

    output = []
    for r0, r1 in row_spans:
        row_out = []
        for c0, c1 in col_spans:
            n = sum(grid[r][c] == marker
                    for r in range(r0, r1)
                    for c in range(c0, c1))
            row_out.append(1 if n == 2 else background)
        output.append(row_out)
    return output
